save(69,dict(paragraphs=[
'Senapati Pradyumna Keshari is an Odia poet whom Kabita Live’s biography identifies as a retired teacher of Odia. In an essay for the Goethe-Institut, poet Ashutosh Parida places him among writers attentive to local life and its often overlooked subjects. Odisha’s government library-selection record also lists his poetry collection “Papatrushna”, published by Prabaha in 2008.',
'His poems here show how far that attention can travel. “Taua” finds endurance and generosity in a blackened cooking griddle, connecting household labour with a speaker’s childhood memories. “Bali Kankada” uses the disappearing sand crab to consider uncertain intimacy, including the distance between a person and their social-media image. “Suryamukhi” turns the sunflower’s devotion towards a landscape of war, where a wounded country’s hope of renewal resists the claims of an occupying power.'
],books=[dict(title='Papatrushna',detail='Odia poetry · Prabaha, 2008. Listed in Odisha’s government library-selection catalogue.',url=u)],sources=[source('Goethe-Institut — contemporary Odia poetry','https://www.goethe.de/ins/in/lp/prj/ptp/mag/en15775736.htm','Ashutosh Parida names this poet among writers representing local life worlds.'),source('Odisha Culture — selected books catalogue',u,'Indexed row 363: PAPATRUSHNA; SENAPATI PRADYUMNA KESHARI; PRABAHA; first edition 2008; POETRY.','search_indexed_table_row; direct PDF fetch failed')],identity_match='Distinctive full author name, Odia poetry context and state bibliography corroborate poet identity; academic retirement remains attributed to captured biography.',poems_read=[dict(id=i,title=t,coverage='Complete original',basis=b) for i,t,b in [(529,'ବାଲି କଙ୍କଡା','Relationship uncertainty, Facebook photographs/comments and sand-crab disappearance.'),(471,'ତାଉଆ','Black griddle endures hammer and flame; nourishment, childhood household and giving.'),(33,'ସୂର୍ଯ୍ୟମୁଖୀ','Sunflower address, missiles, asymmetric invasion and hope of freedom/green renewal.')]],limitations=['Government PDF direct fetch failed; precise indexed row supports book card, but visual PDF table inspection unavailable. Captured ten-book total and employment history not independently verified. Childhood speaker not used to establish personal family facts; no specific war assigned.'],search_queries=['"Senapati Pradyumna Keshari" poet','site:culture.odisha.gov.in "PAPATRUSHNA" "SENAPATI"'],research_leads=[],next_action='Author/editor review; confirm preferred romanised book spelling and complete bibliography.'))
